#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# ──────────────────────────────────────────────────────────────────────────
# 这个向导只做「gh / git 装好之后、必须由你本人完成」的部分：
#   * 选主机（github.com，或企业版 GHES 的域名）
#   * 选 git 协议（https / ssh）
#   * 浏览器授权（gh auth login --web 会打印一次性验证码）
#   * 提交身份（git config --global user.name / user.email）
#   * 配 git 凭据助手并逐项复核
#
# 安装那一步不在这里：Windows 上是
#   winget install --id GitHub.cli -e     # gh
#   winget install --id Git.Git   -e      # git（仓库/PR 命令依赖它）
# 缺哪个本向导会指出来，但不会替你装 —— 那类活儿交给 agent 或包管理器更合适。
#
# 为什么不写 .env：这套东西的权威位置就是 gh 自己的配置
#   ~/.config/gh/config.yml 与 hosts.yml（token 在里面，别提交）
#   以及 git 的 ~/.gitconfig
# 再造一个 .env 只会多出一份没人看的副本，所以本向导不碰 ENV_FILE。
#
# 运行（Git Bash / WSL / macOS / Linux 都可以）：
#   bash setup-gh-cli.sh
# 可以反复跑：已经登录、已经配好的部分会跳过去。
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

banner "GitHub CLI 首次登录与配置"

GH_BIN=""
GIT_BIN=""
# 用绝对路径兜底：winget 装完 PATH 通常要新开终端才刷新，而本次会话里可能还是旧的。
_resolve_bins() {
  if command -v gh >/dev/null 2>&1; then GH_BIN=$(command -v gh); fi
  if [[ -z "$GH_BIN" && -x "/c/Program Files/GitHub CLI/gh.exe" ]]; then GH_BIN="/c/Program Files/GitHub CLI/gh.exe"; fi
  if [[ -z "$GH_BIN" && -x "/usr/bin/gh" ]]; then GH_BIN="/usr/bin/gh"; fi
  if command -v git >/dev/null 2>&1; then GIT_BIN=$(command -v git); fi
  if [[ -z "$GIT_BIN" && -x "/c/Program Files/Git/cmd/git.exe" ]]; then GIT_BIN="/c/Program Files/Git/cmd/git.exe"; fi
  if [[ -z "$GIT_BIN" && -x "/usr/bin/git" ]]; then GIT_BIN="/usr/bin/git"; fi
}

# ── Stage 1/5 ─────────────────────────────────────────────────────────────
stage "前置检查 · gh 与 git 都在位"
_resolve_bins
say "先确认两个工具都能找到（本向导全程用绝对路径，不受 PATH 刷新影响）。"
if [[ -n "$GH_BIN" ]]; then
  say "gh  → $GH_BIN"
  "$GH_BIN" --version 2>/dev/null | head -n 1 | sed 's/^/        /'
else
  warn "PATH 和默认安装位置里都没有 gh。"
fi
if [[ -n "$GIT_BIN" ]]; then
  say "git → $GIT_BIN"
  "$GIT_BIN" --version 2>/dev/null | sed 's/^/        /'
else
  warn "PATH 和默认安装位置里都没有 git。"
fi

if [[ -z "$GH_BIN" || -z "$GIT_BIN" ]]; then
  printf '\n'
  say "缺哪个就先装哪个（装完把终端重开一次再跑本向导）："
  step "winget install --id GitHub.cli -e        # GitHub CLI 官方包"
  step "winget install --id Git.Git   -e         # Git for Windows（同时带来 bash）"
  note "其它系统：https://cli.github.com/ 与 https://git-scm.com/downloads"
  warn "gh 的 repo / pr / issue / clone 都依赖 git，两个都要有。"
  exit 1
fi

say "gh 的仓库与 PR 命令依赖 git，所以两件都得齐 —— 现在齐了。"
pause "继续？"

# ── Stage 2/5 ─────────────────────────────────────────────────────────────
stage "选择主机与 git 协议"
say "这两个选择会写进 gh 的配置（~/.config/gh/config.yml），之后所有 gh 命令都按它走。"
ask GH_HOST "GitHub 主机名（回车=github.com；企业版填你的域名）:"
if [[ -z "$GH_HOST" ]]; then GH_HOST="github.com"; fi
# 顺手容错：有人会把完整网址贴进来
GH_HOST="${GH_HOST#http://}"
GH_HOST="${GH_HOST#https://}"
GH_HOST="${GH_HOST%/}"

while true; do
  ask GIT_PROTOCOL "git 协议 https / ssh（回车=https）:"
  if [[ -z "$GIT_PROTOCOL" ]]; then GIT_PROTOCOL="https"; fi
  case "$GIT_PROTOCOL" in
    https|ssh) break ;;
    *) warn "只能填 https 或 ssh。" ;;
  esac
done

if "$GH_BIN" config set git_protocol "$GIT_PROTOCOL" --host "$GH_HOST"; then
  say "已记录：host=$GH_HOST · git_protocol=$GIT_PROTOCOL"
else
  warn "写 gh 配置失败（不影响继续），可以稍后手动执行："
  note "  gh config set git_protocol $GIT_PROTOCOL --host $GH_HOST"
  SKIPPED+=("gh 配置 git_protocol（gh config set git_protocol $GIT_PROTOCOL --host $GH_HOST）")
fi
if [[ "$GH_HOST" != "github.com" ]]; then
  note "企业版（GHES）请确认域名与网页登录地址一致，例如 ghe.example.com。"
fi

# ── Stage 3/5 ─────────────────────────────────────────────────────────────
stage "浏览器授权 · gh auth login --web"
NEED_LOGIN=1
if "$GH_BIN" auth status --hostname "$GH_HOST" >/dev/null 2>&1; then
  say "gh 在 $GH_HOST 上已经登录过了（重跑本向导时属于正常）。"
  if ! confirm "仍然重新授权一次？"; then NEED_LOGIN=0; fi
fi

if [[ "$NEED_LOGIN" == "1" ]]; then
  say "接下来 gh 会做三件事："
  step "在终端打印一个一次性验证码，形如 XXXX-XXXX"
  step "自动打开浏览器到 https://$GH_HOST/login/device"
  step "你把验证码粘进去、点授权，然后回到这个终端"
  note "浏览器若没自动弹出，就手动打开上面那个地址；验证码以终端显示的为准。"
  if [[ "$GIT_PROTOCOL" == "ssh" ]]; then
    note "协议选了 ssh：gh 还会问是否生成并上传一把新 SSH key，按提示选即可。"
  fi
  pause "准备好了就回车，授权流程立刻开始"

  if "$GH_BIN" auth login --hostname "$GH_HOST" --git-protocol "$GIT_PROTOCOL" --web; then
    say "gh 报告登录成功。"
  else
    warn "gh auth login 没有正常结束。"
  fi

  while ! "$GH_BIN" auth status --hostname "$GH_HOST" >/dev/null 2>&1; do
    warn "认证校验还没通过（验证码过期，或上一步被中断）。"
    if confirm "再试一次 gh auth login？"; then
      "$GH_BIN" auth login --hostname "$GH_HOST" --git-protocol "$GIT_PROTOCOL" --web || true
    else
      warn "先跳过认证 —— 后面两步会因此失败，随时可以重跑本向导。"
      SKIPPED+=("gh 认证未完成（待手动执行：gh auth login --hostname $GH_HOST --web）")
      break
    fi
  done

  if "$GH_BIN" auth status --hostname "$GH_HOST" >/dev/null 2>&1; then
    printf '\n'
    "$GH_BIN" auth status --hostname "$GH_HOST" 2>&1 | sed 's/^/  /'
  fi
fi

# ── Stage 4/5 ─────────────────────────────────────────────────────────────
stage "提交身份 · git config --global"
say "git 每次提交都要写「是谁提交的」。先用你 GitHub 上的资料算两个默认值。"
GH_LOGIN=$("$GH_BIN" api user --jq .login 2>/dev/null || true)
GH_ID=$("$GH_BIN" api user --jq .id 2>/dev/null || true)
GH_NAME=$("$GH_BIN" api user --jq '.name // empty' 2>/dev/null || true)
DEFAULT_NAME="$GH_NAME"
if [[ -z "$DEFAULT_NAME" ]]; then DEFAULT_NAME="$GH_LOGIN"; fi
DEFAULT_EMAIL=""
if [[ -n "$GH_ID" && -n "$GH_LOGIN" ]]; then
  DEFAULT_EMAIL="${GH_ID}+${GH_LOGIN}@users.noreply.github.com"
fi
if [[ -n "$GH_LOGIN" ]]; then say "已认证账号：$GH_LOGIN"; fi

while true; do
  ask GIT_USER_NAME "提交显示名（回车=${DEFAULT_NAME:-自己填}）:"
  if [[ -z "$GIT_USER_NAME" ]]; then GIT_USER_NAME="$DEFAULT_NAME"; fi
  if [[ -n "$GIT_USER_NAME" ]]; then break; fi
  warn "显示名不能为空。"
done

say "邮箱建议用 GitHub 提供的 noreply 地址：真实邮箱不用出现在每一条提交里。"
if [[ -z "$DEFAULT_EMAIL" ]]; then
  step "下面这个页面里能看到形如 12345678+yourname@users.noreply.github.com 的地址"
  open_url "https://github.com/settings/emails"
fi
while true; do
  ask GIT_USER_EMAIL "提交邮箱（回车=${DEFAULT_EMAIL:-自己填}）:"
  if [[ -z "$GIT_USER_EMAIL" ]]; then GIT_USER_EMAIL="$DEFAULT_EMAIL"; fi
  if [[ -n "$GIT_USER_EMAIL" ]]; then break; fi
  warn "邮箱不能为空；也可以在 GitHub → Settings → Emails 里找到 noreply 地址。"
done

if "$GIT_BIN" config --global user.name "$GIT_USER_NAME" \
   && "$GIT_BIN" config --global user.email "$GIT_USER_EMAIL"; then
  say "已写入 ~/.gitconfig：user.name=$GIT_USER_NAME · user.email=$GIT_USER_EMAIL"
else
  warn "写 ~/.gitconfig 失败，请手动执行："
  note "  git config --global user.name  \"$GIT_USER_NAME\""
  note "  git config --global user.email \"$GIT_USER_EMAIL\""
  SKIPPED+=("git 提交身份（git config --global user.name / user.email）")
fi

# ── Stage 5/5 ─────────────────────────────────────────────────────────────
stage "凭据助手与收尾复核"
if [[ "$GIT_PROTOCOL" == "https" ]]; then
  say "让 git 用 gh 当凭据助手：以后 git push / pull 不再弹账号密码，也不用存 PAT。"
  if "$GIT_BIN" config --global --get-all credential."https://$GH_HOST".helper 2>/dev/null | grep -q 'gh auth git-credential'; then
    say "已经配过了，跳过。"
  elif "$GH_BIN" auth setup-git --hostname "$GH_HOST"; then
    say "已配置。"
  else
    warn "gh auth setup-git 失败，可稍后手动执行：gh auth setup-git --hostname $GH_HOST"
    SKIPPED+=("git 凭据助手（gh auth setup-git --hostname $GH_HOST）")
  fi
else
  say "协议是 ssh：认证走 SSH key，不需要 git 凭据助手（gh 登录时已经问过是否上传 key）。"
  step "自测一条：ssh -T git@$GH_HOST"
fi

printf '\n'
say "逐项复核："
if "$GH_BIN" auth status --hostname "$GH_HOST" >/dev/null 2>&1; then
  say "  ✓ gh 已登录（gh auth status 通过）"
else
  warn "  ✗ gh 尚未登录"
  SKIPPED+=("gh 认证（gh auth login --hostname $GH_HOST --web）")
fi

WHO=$("$GH_BIN" api user --jq .login 2>/dev/null || true)
if [[ -n "$WHO" ]]; then
  say "  ✓ token 可用：API 返回账号 $WHO"
else
  warn "  ✗ token 调 API 失败"
  SKIPPED+=("token 复核（gh api user）")
fi

NAME_NOW=$("$GIT_BIN" config --global --get user.name 2>/dev/null || true)
MAIL_NOW=$("$GIT_BIN" config --global --get user.email 2>/dev/null || true)
if [[ -n "$NAME_NOW" && -n "$MAIL_NOW" ]]; then
  say "  ✓ 提交身份：$NAME_NOW <$MAIL_NOW>"
else
  warn "  ✗ 提交身份不完整"
  SKIPPED+=("git 提交身份（git config --global user.name / user.email）")
fi

HELPER=$("$GIT_BIN" config --global --get-all credential."https://$GH_HOST".helper 2>/dev/null | tr '\n' ' ' || true)
if [[ "$GIT_PROTOCOL" == "https" ]]; then
  if [[ -n "$HELPER" ]]; then
    say "  ✓ 凭据助手：$HELPER"
  else
    warn "  ✗ 凭据助手没配上"
    SKIPPED+=("git 凭据助手（gh auth setup-git --hostname $GH_HOST）")
  fi
fi

printf '\n'
note "写在哪里："
note "  gh  → ~/.config/gh/config.yml（git_protocol 等）与 hosts.yml（token，别提交）"
note "  git → ~/.gitconfig（user.name / user.email / credential.helper）"
step "试一条真命令：gh repo list --limit 5"
pause "全部做完，回车收尾"

printf '\n'
note "本次结果：host=$GH_HOST · git_protocol=$GIT_PROTOCOL"
note "          user.name=$GIT_USER_NAME · user.email=$GIT_USER_EMAIL"

finish